import {teamProfile} from './team-profile.mjs';
const $=id=>document.getElementById(id),dialog=$('start-dialog'),frame=$('preview');let setup=null,connection=null,bridge=false,sourceSeen=false,generation=0,appCheck=null;
async function api(group,route,body={}){const r=await fetch(`/api/${group}/${route}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'연결 정보를 확인하지 못했습니다.');return data;}
function render(){const project=setup?.project;let same=false;try{same=project&&new URL(frame.src).origin===new URL(project.url).origin;}catch{}
 const checks=[['앱 실행',appCheck?.message||'실행 상태 확인 중…'],['원본 폴더',setup?.configured?`${project.name} · 연결됨`:setup?.problem||'등록 필요 · 아래 AI 요청을 복사하면 폴더 찾기부터 도움받을 수 있습니다.'],['화면 편집',bridge?(same&&sourceSeen?'화면과 선택 요소의 코드 연결 확인됨':'화면 편집 연결됨 · 요소를 선택하면 원본 연결을 확인합니다.'):'화면 연결 대기 · 앱을 실행한 뒤 화면을 열어 확인하세요.'],['PR 저장소',connection?.connected?`${connection.repository} · 연결됨`:connection?.needsAuthentication?'저장소 주소 보관됨 · PR을 보낼 때 다시 인증하세요.':'PR을 보낼 때 연결하면 됩니다.']];
 $('setup-checks').replaceChildren(...checks.map(([title,body])=>{const li=document.createElement('li'),strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=title;span.textContent=body;li.append(strong,span);return li;}));$('start-edit').disabled=!project;$('start-edit').textContent=bridge&&same?'편집 계속하기':'편집 화면 열기';
 const openApp=$('setup-open-app');openApp.hidden=!project;if(project)openApp.href=project.url;
 $('setup-handoff').value=`나는 코드를 직접 다루지 않는 사용자입니다. Dragger 폴더의 docs/AI-SETUP.md와 docs/TECHNICAL.md를 읽고 서비스 연결을 진행해 주세요.
서비스: ${project?.name||'아직 선택하지 않음'}
원본 폴더: ${project?.repo||'모름 — 서비스 이름 또는 저장소 주소를 물어본 뒤 찾아 주세요.'}
앱 주소: ${project?.url||'모름 — 앱 실행 후 확인해 주세요.'}
현재 상태: ${appCheck?.message||'앱 실행 미확인'}
1. 원본 폴더와 실행 방법을 확인하고 필요한 설치·설정을 직접 진행해 주세요. 앱에 필요한 회사 권한이나 계정이 없다면 무엇을 받아야 하는지만 쉬운 말로 알려 주세요.
2. 기존 설정을 보존하며 공통 레이아웃과 원본 코드 연결을 준비하고 앱을 실행해 주세요. 실제 서버를 샘플 데이터로 대체하지 마세요.
3. Dragger에 폴더와 앱 주소를 등록하고 로그인·페이지 이동·요소 선택을 확인해 주세요. 토큰·비밀번호 입력은 제가 서비스 화면에서 직접 할게요.
4. 다음 실행 방법을 알려 주세요. 연결되지 않은 부분을 완료했다고 보고하지 말고, PR 업로드는 제가 요청할 때 진행해 주세요.`;
}
async function refresh(fill=false){const run=++generation;try{const [a,b]=await Promise.all([api('setup','status'),api('connection','status')]);if(run!==generation)return;setup=a;connection=b;if(fill&&a.project){$('setup-name').value=a.project.name;$('setup-url').value=a.project.url;$('setup-repo').value=a.project.repo;}render();if(!a.configured)$('setup-ai').open=true;const checked=await api('setup','check-app');if(run!==generation)return;appCheck=checked;render();}catch(e){$('setup-result').textContent='Dragger에 연결하지 못했습니다. 실행 창이 열려 있는지 확인한 뒤 다시 확인을 눌러 주세요.';}}
function open(){dialog.showModal();void refresh(true);}
$('open-start').onclick=open;$('empty-start').onclick=open;$('start-close').onclick=()=>dialog.close();$('setup-refresh').onclick=()=>refresh();
$('start-edit').onclick=()=>{if(!setup?.project)return;let same=false;try{same=new URL(frame.src).origin===new URL(setup.project.url).origin;}catch{}if(!same)window.dispatchEvent(new CustomEvent('dragger:open-project',{detail:setup.project}));dialog.close();if(same&&bridge)$('edit').click();};
$('setup-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('setup-result').textContent='원본 폴더를 확인하고 있습니다…';try{const next={name:$('setup-name').value,url:$('setup-url').value,repo:$('setup-repo').value};const last=JSON.parse(localStorage.getItem('dragger.lastApplied')||'null');if(last?.id&&setup?.project&&next.repo!==setup.project.repo)throw Error('현재 코드 적용 기록이 남아 있습니다. 기존 서비스의 PR·되돌리기 작업을 마친 뒤 원본 폴더를 바꿔 주세요.');setup=await api('setup','save',next);appCheck=null;render();$('setup-result').textContent='저장했습니다. 다음 실행에도 이 연결을 사용합니다.';window.dispatchEvent(new CustomEvent('dragger:open-project',{detail:setup.project}));await refresh();}catch(e){$('setup-result').textContent=e.message;}finally{button.disabled=false;}};
$('setup-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000)throw Error('연결 파일이 너무 큽니다. 팀에서 받은 Dragger JSON 파일을 선택하세요.');const data=teamProfile(JSON.parse(await file.text()));$('setup-name').value=data.name;$('setup-url').value=data.url;$('setup-repo').value='';$('setup-project').open=true;$('setup-result').textContent='서비스 정보를 불러왔습니다. 이 컴퓨터의 원본 폴더를 입력한 뒤 저장하세요.';}catch(e){$('setup-result').textContent=e.message;}finally{e.target.value='';}};
$('setup-export').onclick=()=>{try{const data=teamProfile({schema:'dragger/team-v1',name:$('setup-name').value,url:$('setup-url').value});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='dragger-team.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('setup-result').textContent='서비스 이름과 화면 주소만 저장했습니다. 각 팀원은 자신의 컴퓨터에서 앱과 원본 폴더를 준비해야 합니다.';}catch(e){$('setup-result').textContent=e.message;}};
for(const provider of ['github','bitbucket'])$('setup-'+provider).onclick=()=>{dialog.close();$(provider+'-connect').click();};
$('setup-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('setup-handoff').value);$('setup-result').textContent='복사했습니다. Dragger 폴더를 연 AI 코딩 도구에 붙여넣으세요.';}catch{$('setup-handoff').select();$('setup-result').textContent='선택된 내용을 복사해 주세요.';}};
new MutationObserver(()=>{bridge=false;sourceSeen=false;render();}).observe(frame,{attributes:true,attributeFilter:['src']});
window.addEventListener('message',e=>{let origin;try{origin=new URL(frame.src).origin;}catch{return;}if(e.source!==frame.contentWindow||e.origin!==origin)return;if(e.data?.type==='dragger:ready')bridge=true;if(e.data?.type==='dragger:selection')sourceSeen=!!e.data.source;render();});
await refresh(true);if(!$('services').options.length){if(setup?.project)window.dispatchEvent(new CustomEvent('dragger:open-project',{detail:setup.project}));else open();}
